<script setup lang="ts">
import type { RuleGroup, Condition } from '../../../shared/contracts.js';
const props = defineProps<{ modelValue: RuleGroup[] }>();
const emit = defineEmits<{ 'update:modelValue': [value: RuleGroup[]] }>();
const fields = [ ['discount', '实际折扣'], ['backendPrice', '后台标价（元）'], ['before', '优惠前价（元）'], ['after', '优惠后价（元）'], ['saving', '优惠金额（元）'], ['priceDifference', '优惠前与后台差额（元）'], ['title', '商品标题'], ['specs', '完整规格'], ['productId', '商品 ID'], ['skuId', 'SKU ID'], ['status', '数据状态'] ];
const numericOps = [['lt', '小于 <'], ['lte', '小于等于 ≤'], ['eq', '等于 ='], ['ne', '不等于 ≠'], ['gte', '大于等于 ≥'], ['gt', '大于 >'], ['between', '区间']];
const textOps = [['contains', '包含'], ['notContains', '不包含'], ['eq', '等于'], ['ne', '不等于'], ['in', '属于列表'], ['notIn', '不属于列表']];
function textField(field: string) { return ['title', 'specs', 'productId', 'skuId', 'status'].includes(field); }
function change(edit: (groups: RuleGroup[]) => void) { const groups: RuleGroup[] = JSON.parse(JSON.stringify(props.modelValue)); edit(groups); emit('update:modelValue', groups); }
function addGroup() { change(groups => groups.push({ mode: 'all', conditions: [{ field: 'discount', op: 'lt', value: '8.5' }] })); }
function update(group: number, index: number, field: keyof Condition, value: unknown) { change(groups => { const item = groups[group]!.conditions[index]!; Object.assign(item, { [field]: value }); if (field === 'field') item.op = textField(String(value)) ? 'contains' : 'lt'; }); }
</script>
<template><div class="rule-editor"><div v-for="(group, gi) in modelValue" :key="gi" class="rule-group"><div class="rule-group-head"><strong>条件组 {{ gi + 1 }}</strong><el-select :model-value="group.mode" class="compact-select" @update:model-value="(v: string | number | boolean) => change(g => { g[gi]!.mode = v as 'all' | 'any'; })"><el-option value="all" label="全部满足（AND）" /><el-option value="any" label="任意满足（OR）" /></el-select><el-button text type="danger" @click="change(g => { g.splice(gi, 1); })">删除组</el-button></div><div v-for="(condition, ci) in group.conditions" :key="ci" class="condition-row"><el-select :model-value="condition.field" @update:model-value="(v: string | number | boolean) => update(gi, ci, 'field', v)"><el-option v-for="[value, label] in fields" :key="value" :value="value!" :label="label" /></el-select><el-select :model-value="condition.op" @update:model-value="(v: string | number | boolean) => update(gi, ci, 'op', v)"><el-option v-for="[value, label] in textField(condition.field) ? textOps : numericOps" :key="value" :value="value!" :label="label" /></el-select><el-input :model-value="condition.value" :placeholder="condition.field === 'discount' ? '如 8.5 或 8.5折' : condition.field === 'status' ? 'ok / error / stale / partial' : '输入条件值'" @update:model-value="(v: string | number | boolean) => update(gi, ci, 'value', v)" /><template v-if="condition.op === 'between'"><span>至</span><el-input :model-value="condition.upper" placeholder="上限" @update:model-value="(v: string | number | boolean) => update(gi, ci, 'upper', v)" /><el-checkbox :model-value="condition.includeLower !== false" @update:model-value="(v: string | number | boolean) => update(gi, ci, 'includeLower', v)">含下限</el-checkbox><el-checkbox :model-value="condition.includeUpper !== false" @update:model-value="(v: string | number | boolean) => update(gi, ci, 'includeUpper', v)">含上限</el-checkbox></template><el-button text type="danger" @click="change(g => { g[gi]!.conditions.splice(ci, 1); })">移除</el-button></div><el-button text type="primary" @click="change(g => { g[gi]!.conditions.push({ field: 'discount', op: 'lt', value: '8.5' }); })">＋ 添加条件</el-button></div><el-button plain @click="addGroup">＋ 添加条件组</el-button><span class="form-hint">组间全部满足；缺价、零后台价和陈旧数据不按 0 判断。折扣阈值 0～10，最多两位小数。</span></div></template>
